mapper.update:
UPDATE sys_log
SET fl_no=#{flNo}
WHERE task_id = #{taskId}

mapper.select:
        SELECT
        title,
        method,
        request_body AS requestBody,
        response_body AS responseBody,
        create_by AS createBy,
        create_date AS createDate,
        fl_no AS flNo,
        task_id AS taskId,
        ip
        FROM sys_log
        
            
                AND fl_no = #{flNo}
            
            
                AND title = #{title}
            
            
                AND task_id = #{taskId}
            
            
                AND create_date = #{taskId}
            
            
                AND create_date >= #{startTime}
            
            
                AND create_date <= #{endTime}
            
            
                AND ip = #{ip}
